package net.civeira.phylax.feature.oauth.mfa.application;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.UserMfaRecoveryCode;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.UserMfaRecoveryCodeChangeSet;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.gateway.UserMfaRecoveryCodeCommandRepositoryGateway;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.gateway.UserMfaRecoveryCodeQueryRepositoryGateway;
import net.civeira.phylax.feature.access.usermfarecoverycode.domain.valueobject.CodeHashVO;
import net.civeira.phylax.feature.identity.user.domain.UserReference;
import net.civeira.phylax.feature.oauth.mfa.domain.gateway.RecoveryCodeConsumptionGateway;

class MfaRecoveryServiceUnitTest {

  @Test
  @DisplayName("A matching code counts only when the atomic consumption wins")
  void consume_only_when_winning() {
    PasswordHasher hasher = new PasswordHasher();
    UserMfaRecoveryCode code = UserMfaRecoveryCode
        .create(new UserMfaRecoveryCodeChangeSet().newUid().user(UserReference.of("alice"))
            .codeHash(CodeHashVO.fromStored(hasher.hash("ABCD-EFGH"))));
    UserMfaRecoveryCodeQueryRepositoryGateway read =
        Mockito.mock(UserMfaRecoveryCodeQueryRepositoryGateway.class);
    Mockito.when(read.list(Mockito.any())).thenReturn(List.of(code));
    RecoveryCodeConsumptionGateway consumption = Mockito.mock(RecoveryCodeConsumptionGateway.class);
    MfaRecoveryService service = new MfaRecoveryService(read,
        Mockito.mock(UserMfaRecoveryCodeCommandRepositoryGateway.class), hasher, consumption);

    Mockito.when(consumption.consume(code.getUid(), "alice")).thenReturn(true, false);
    Assertions.assertTrue(service.consumeCode("alice", "ABCD-EFGH"));
    Assertions.assertFalse(service.consumeCode("alice", "ABCD-EFGH"), "The race was lost");
    Assertions.assertFalse(service.consumeCode("alice", "WRONG-CODE"));
  }
}
